#include <bits/stdc++.h>
using namespace std;

const int maxn = 5005;
typedef int T;
const T INF = 1e9+7;
const int K = 100;

struct Edge {
    int u, v;
    T cap, flow, cost;
};

struct FlowSolver {
    int n, m, s, t;
    vector<int> adj[maxn];
    vector<Edge> edges;
    T dist[maxn];
    bool inQueue[maxn];
    int parent[maxn];
    T minCap[maxn];

    explicit FlowSolver(int nodes) : n(nodes) {}

    void add_edge(int u, int v, T capacity, T cost) {
        edges.push_back({u, v, capacity, 0, cost});
        edges.push_back({v, u, 0, 0, -cost});
        m = (int)edges.size();
        adj[u].push_back(m - 2);
        adj[v].push_back(m - 1);
    }

    bool findPath(T &flow, T &cost) {
        for (int i = 0; i < n; ++i) dist[i] = INF;
        memset(inQueue, 0, sizeof(inQueue));
        dist[s] = 0; inQueue[s] = true; parent[s] = -1; minCap[s] = INF;

        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inQueue[u] = false;
            for (int i : adj[u]) {
                Edge &e = edges[i];
                if (e.cap > e.flow && dist[e.v] > dist[u] + e.cost) {
                    dist[e.v] = dist[u] + e.cost;
                    parent[e.v] = i;
                    minCap[e.v] = min(minCap[u], e.cap - e.flow);
                    if (!inQueue[e.v]) {
                        q.push(e.v);
                        inQueue[e.v] = true;
                    }
                }
            }
        }
        if (dist[t] == INF) return false;
        flow = minCap[t];
        cost = dist[t];
        int u = t;
        while (u != s) {
            edges[parent[u]].flow += flow;
            edges[parent[u] ^ 1].flow -= flow;
            u = edges[parent[u]].u;
        }
        return true;
    }

    pair<T, T> run(int s, int t) {
        this->s = s; this->t = t;
        T totalFlow = 0, totalCost = 0;
        T f = 0, d = 0;
        while (findPath(f, d)) {
            totalFlow += f;
            totalCost += f * d;
        }
        return make_pair(totalFlow, totalCost);
    }
};

int main() {
    int n, m, k, C, D;
    cin >> n >> m >> k >> C >> D;

    FlowSolver solver(n * K + 2);
    int source = n * K, sink = n * K + 1;

    for (int i = 0; i < K; ++i)
        solver.add_edge(i, sink, k, C * i);

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        x--;
        solver.add_edge(source, x * K, 1, 0);
    }

    for (int i = 0; i < n; ++i)
        for (int j = 1; j < K; ++j)
            solver.add_edge(i * K + j - 1, i * K + j, k, 0);

    for (int _ = 0; _ < m; ++_) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        for (int j = 1; j < K; ++j) {
            int a = u * K + j - 1, b = v * K + j;
            int c = v * K + j - 1, d = u * K + j;
            for (int i = 1, cc = D; i <= k; ++i, cc += 2 * D) {
                solver.add_edge(a, b, 1, cc);
                solver.add_edge(c, d, 1, cc);
            }
        }
    }
    auto res = solver.run(source, sink);
    cout << res.second << endl;
}
